def signed_in(E, tgt):
    """(Mp, Mm, n_edges) for edge set E into bool target mask tgt."""
    sel = E & tgt[dst_all]
    v = vals_all[sel]
    return (float(v[v > 0].sum()), float(-v[v < 0].sum()), int(sel.sum()))


